import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import org.apache.commons.text.lookup.StringLookupFactory;

public class TemplateServlet extends HttpServlet {
    private static final Map<String, String> TEMPLATES = new HashMap<>();

    static {
        TEMPLATES.put("welcome", "Hello ${user.name}, your account #${user.id} is active.");
        TEMPLATES.put("alert", "ALERT: ${alert.message} at ${alert.timestamp}");
        TEMPLATES.put("report", "Report for ${report.title}: ${report.summary}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String templateName = req.getParameter("template");
        String customTemplate = req.getParameter("custom");
        String userData = req.getParameter("data");

        if (templateName == null && customTemplate == null) {
            resp.sendError(400, "Missing template or custom parameter");
            return;
        }

        String templateStr;
        if (customTemplate != null && !customTemplate.isEmpty()) {
            // Allow custom templates for premium users
            String premiumHeader = req.getHeader("X-Premium-User");
            if (premiumHeader == null || !premiumHeader.equals("true")) {
                resp.sendError(403, "Custom templates require premium access");
                return;
            }
            templateStr = customTemplate;
        } else {
            templateStr = TEMPLATES.get(templateName);
            if (templateStr == null) {
                resp.sendError(404, "Template not found");
                return;
            }
        }

        // Parse user data as key=value pairs
        Map<String, String> values = new HashMap<>();
        if (userData != null) {
            for (String pair : userData.split("&")) {
                String[] kv = pair.split("=", 2);
                if (kv.length == 2) {
                    values.put(URLDecoder.decode(kv[0], "UTF-8"),
                              URLDecoder.decode(kv[1], "UTF-8"));
                }
            }
        }

        // Perform substitution using Apache Commons Text
        StringSubstitutor substitutor = new StringSubstitutor(
            StringLookupFactory.INSTANCE.interpolatorStringLookup(values, null, true)
        );
        substitutor.setEnableSubstitutionInVariables(true);

        String result = substitutor.replace(templateStr);

        resp.setContentType("text/plain");
        resp.getWriter().write(result);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        StringBuilder sb = new StringBuilder("{\"templates\":[");
        int i = 0;
        for (String key : TEMPLATES.keySet()) {
            if (i++ > 0) sb.append(",");
            sb.append("\"" + key + "\"");
        }
        sb.append("]}");
        resp.getWriter().write(sb.toString());
    }
}
